<script setup lang="ts">
const {request}=useAdminApi();const rows=ref<any[]>([]);const page=ref(1);const lastPage=ref(1);const error=ref('');const dialog=ref(false);const id=ref<number|null>(null);const form=reactive({title:'',slug:'',is_active:true});
async function load(){try{const result:any=await request(`/admin/specialties?page=${page.value}`);lastPage.value=result.last_page||result.meta?.last_page||1;rows.value=result.data;}catch(e:any){error.value=e?.data?.message||'خطا';}}onMounted(load);
function add(){id.value=null;Object.assign(form,{title:'',slug:'',is_active:true});dialog.value=true;}
function edit(r:any){id.value=r.id;Object.assign(form,{title:r.title,slug:r.slug,is_active:r.is_active});dialog.value=true;}
async function save(){try{await request(`/admin/specialties${id.value?'/'+id.value:''}`,{method:id.value?'PUT':'POST',body:form});dialog.value=false;await load();}catch(e:any){error.value=JSON.stringify(e?.data?.errors||e?.data?.message||'خطا');}}
async function remove(r:any){if(!confirm('حذف تخصص؟'))return;try{await request(`/admin/specialties/${r.id}`,{method:'DELETE'});await load();}catch(e:any){error.value=e?.data?.message||'خطا';}}
</script><template><div dir="rtl"><div class="d-flex justify-space-between mb-5"><h2>تخصص‌ها</h2><v-btn @click="add">افزودن</v-btn></div><v-alert v-if="error" type="error">{{error}}</v-alert><v-table><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.title}}</td><td>{{r.slug}}</td><td>{{r.is_active?'فعال':'غیرفعال'}}</td><td><v-btn size="small" @click="edit(r)">ویرایش</v-btn><v-btn size="small" color="error" @click="remove(r)">حذف</v-btn></td></tr></tbody></v-table><div class="d-flex ga-3 align-center mt-4"><v-btn :disabled="page<=1" @click="page--;load()">قبلی</v-btn><span>صفحه {{page}} از {{lastPage}}</span><v-btn :disabled="page>=lastPage" @click="page++;load()">بعدی</v-btn></div><v-dialog v-model="dialog" max-width="500"><v-card class="pa-6" dir="rtl"><v-text-field v-model="form.title" label="عنوان"/><v-text-field v-model="form.slug" label="اسلاگ"/><v-switch v-model="form.is_active" label="فعال"/><v-btn @click="save">ذخیره</v-btn></v-card></v-dialog></div></template>
